#!/usr/bin/env node
/**
 * Where the bytes in a production JS bundle come from, by npm package and by
 * app folder, using the bundle's source map.
 *
 * 1. Export a plain-JS production bundle with a source map (the output dir
 *    must be inside the project; --clear avoids stale transforms cached by
 *    another checkout):
 *      NODE_ENV=production npx expo export --platform android \
 *        --output-dir .expo/perf-export --source-maps --no-bytecode --clear
 * 2. node scripts/perf/bundle-attribution.js .expo/perf-export/_expo/static/js/android/entry-*.js
 * 3. Delete .expo/perf-export afterwards — a repo-wide ESLint run chokes on it.
 *
 * Sizes are minified JS bytes attributed through the source map; they track
 * Hermes bytecode size closely enough to rank what to cut.
 */
const fs = require("fs");
const path = require("path");

const bundlePath = process.argv[2];
if (!bundlePath || !fs.existsSync(bundlePath) || !fs.existsSync(bundlePath + ".map")) {
  console.error("usage: node scripts/perf/bundle-attribution.js <bundle.js>  (expects <bundle.js>.map next to it)");
  process.exit(1);
}
const root = process.cwd();
const { SourceMapConsumer } = require(path.join(root, "node_modules/source-map-js"));

const lines = fs.readFileSync(bundlePath, "utf8").split("\n");
const consumer = new SourceMapConsumer(JSON.parse(fs.readFileSync(bundlePath + ".map", "utf8")));

// Each mapping owns the generated bytes up to the next mapping on its line.
const byLine = new Map();
consumer.eachMapping((m) => {
  if (!byLine.has(m.generatedLine)) byLine.set(m.generatedLine, []);
  byLine.get(m.generatedLine).push(m);
});
const bySource = new Map();
let totalBytes = 0;
for (const line of lines) totalBytes += line.length + 1;
for (const [lineNo, mappings] of byLine) {
  mappings.sort((a, b) => a.generatedColumn - b.generatedColumn);
  const lineLen = (lines[lineNo - 1] || "").length;
  mappings.forEach((m, i) => {
    const end = i + 1 < mappings.length ? mappings[i + 1].generatedColumn : lineLen;
    const src = m.source || "<unmapped>";
    bySource.set(src, (bySource.get(src) || 0) + Math.max(0, end - m.generatedColumn));
  });
}

function bucket(src) {
  const s = src.replace(/\\/g, "/");
  const nm = s.lastIndexOf("node_modules/");
  if (nm !== -1) {
    const parts = s.slice(nm + "node_modules/".length).split("/");
    return { group: "npm", key: parts[0].startsWith("@") ? `${parts[0]}/${parts[1]}` : parts[0] };
  }
  const rel = (s.includes(root) ? s.slice(s.indexOf(root) + root.length) : s).replace(/^\/+/, "");
  const parts = rel.split("/");
  // app/(group)/folder and components/folder are the useful granularity.
  const depth = parts[0] === "app" ? 3 : parts[0] === "components" ? 2 : 1;
  return { group: "app", key: parts.slice(0, Math.min(depth, parts.length - 1)).join("/") || rel, file: rel };
}

const groups = { npm: new Map(), app: new Map() };
const appFiles = new Map();
for (const [src, bytes] of bySource) {
  const b = bucket(src);
  const g = groups[b.group];
  const cur = g.get(b.key) || { bytes: 0, modules: 0 };
  cur.bytes += bytes;
  cur.modules += 1;
  g.set(b.key, cur);
  if (b.file) appFiles.set(b.file, bytes);
}

const kb = (n) => `${(n / 1024).toFixed(0).padStart(6)} KB`;
const top = (map, n) => [...map].sort((a, b) => b[1].bytes - a[1].bytes).slice(0, n);
const sum = (map) => [...map.values()].reduce((a, v) => a + v.bytes, 0);

console.log(`bundle ${kb(totalBytes)}  sources ${bySource.size}  (npm ${kb(sum(groups.npm))}, app ${kb(sum(groups.app))})`);
console.log("\n== npm packages ==");
for (const [k, v] of top(groups.npm, 40)) console.log(`${kb(v.bytes)} ${String(v.modules).padStart(5)} mods  ${k}`);
console.log("\n== app code by folder ==");
for (const [k, v] of top(groups.app, 40)) console.log(`${kb(v.bytes)} ${String(v.modules).padStart(5)} mods  ${k}`);
console.log("\n== largest app files ==");
for (const [f, b] of [...appFiles].sort((a, c) => c[1] - a[1]).slice(0, 20)) console.log(`${kb(b)}  ${f}`);
